#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxAscendingSum(vector<int>& nums) {
        int curr = nums[0];
        int mx = curr;
        for (int i = 1; i < nums.size(); ++i) {
            if (nums[i] > nums[i - 1]) {
                curr += nums[i];
            } else {
                curr = nums[i];
            }
            mx = max(mx, curr);
        }
        return mx;
    }
};

class Solution {
    public int maxAscendingSum(int[] nums) {
        int curr = nums[0];
        int mx = curr;
        for (int i = 1; i < nums.length; ++i) {
            if (nums[i] > nums[i - 1]) {
                curr += nums[i];
            } else {
                curr = nums[i];
            }
            mx = Math.max(mx, curr);
        }
        return mx;
    }
}

