var maxAscendingSum = function(nums) {
    let curr = nums[0];
    let mx = curr;
    for (let i = 1; i < nums.length; ++i) {
        if (nums[i] > nums[i - 1]) {
            curr += nums[i];
        } else {
            curr = nums[i];
        }
        mx = Math.max(mx, curr);
    }
    return mx;
};
